using MessagePack.SourceGenerator;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class GeneratedFormatterForReferencedTypeTests
{
    private const string ProjectASource = """
        namespace ProjectA
        {
            public class MyType
            {
                public int Id { get; set; }
                public string Name { get; set; }
            }
        }
        """;

    private static async Task<ImmutableArray<MetadataReference>> GetFrameworkReferencesAsync()
        => await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);

    private static MetadataReference CompileProjectA(string source, IEnumerable<MetadataReference> references)
    {
        CSharpCompilation compilation = CSharpCompilation.Create(
            "ProjectA",
            new[] { CSharpSyntaxTree.ParseText(source, new CSharpParseOptions(LanguageVersion.Latest)) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        using MemoryStream stream = new();
        var emitResult = compilation.Emit(stream);
        Assert.True(emitResult.Success, string.Join(Environment.NewLine, emitResult.Diagnostics));
        return MetadataReference.CreateFromImage(stream.ToArray());
    }

    private static (Compilation Output, ImmutableArray<Diagnostic> GeneratorDiagnostics, GeneratorDriverRunResult RunResult) RunGenerator(string source, IEnumerable<MetadataReference> references)
    {
        CSharpParseOptions parseOptions = new(LanguageVersion.Latest);
        CSharpCompilation compilation = CSharpCompilation.Create(
            "ProjectB",
            new[] { CSharpSyntaxTree.ParseText(source, parseOptions) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        GeneratorDriver driver = CSharpGeneratorDriver.Create(new[] { new MessagePackGenerator().AsSourceGenerator() }, parseOptions: parseOptions);
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out ImmutableArray<Diagnostic> diagnostics);
        return (output, diagnostics, driver.GetRunResult());
    }

    private static async Task<(Compilation Output, ImmutableArray<Diagnostic> GeneratorDiagnostics, GeneratorDriverRunResult RunResult)> RunProjectBAsync(string projectBSource)
    {
        ImmutableArray<MetadataReference> framework = await GetFrameworkReferencesAsync();
        MetadataReference projectA = CompileProjectA(ProjectASource, framework);
        List<MetadataReference> references = framework.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)).ToList();
        references.Add(projectA);
        return RunGenerator(projectBSource, references);
    }

    private static void AssertNoErrors(Compilation output, ImmutableArray<Diagnostic> generatorDiagnostics)
    {
        var errors = generatorDiagnostics.Concat(output.GetDiagnostics()).Where(d => d.Severity == DiagnosticSeverity.Error).ToList();
        Assert.True(errors.Count == 0, string.Join(Environment.NewLine, errors));
    }

    [Fact]
    public async Task BodylessFormatterForReferencedType_CompilesWithoutErrors()
    {
        string projectB = """
            using MessagePack;
            using MessagePack.Formatters;

            namespace ProjectB
            {
                [GeneratedMessagePackFormatter]
                partial class MyTypeFormatter : IMessagePackFormatter<ProjectA.MyType>;

                [GeneratedMessagePackResolver]
                partial class MyResolver { }
            }
            """;

        var (output, generatorDiagnostics, _) = await RunProjectBAsync(projectB);
        AssertNoErrors(output, generatorDiagnostics);
    }

    [Fact]
    public async Task FormatterForReferencedType_WithoutDeclaredResolver_CompilesWithoutErrors()
    {
        string projectB = """
            using MessagePack;
            using MessagePack.Formatters;

            namespace ProjectB
            {
                [GeneratedMessagePackFormatter]
                public partial class MyTypeFormatter : IMessagePackFormatter<ProjectA.MyType>
                {
                }
            }
            """;

        var (output, generatorDiagnostics, _) = await RunProjectBAsync(projectB);
        AssertNoErrors(output, generatorDiagnostics);
    }

    [Fact]
    public async Task FormatterForReferencedType_GeneratedSourceCoversPublicMembers()
    {
        string projectB = """
            using MessagePack;
            using MessagePack.Formatters;

            namespace ProjectB
            {
                [GeneratedMessagePackFormatter]
                partial class MyTypeFormatter : IMessagePackFormatter<ProjectA.MyType>;

                [GeneratedMessagePackResolver]
                partial class MyResolver { }
            }
            """;

        var (_, _, runResult) = await RunProjectBAsync(projectB);
        List<string> formatterSources = runResult.GeneratedTrees
            .Select(t => t.GetText().ToString())
            .Where(t => t.Contains("MyTypeFormatter") && t.Contains("Serialize"))
            .ToList();
        Assert.NotEmpty(formatterSources);
        string all = string.Join(Environment.NewLine, formatterSources);
        Assert.Contains("Id", all);
        Assert.Contains("Name", all);
    }
}

