using MessagePack.SourceGenerator;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class GeneratedFormatterHonoursAttributesTests
{
    private const string ProjectBSource = """
        using MessagePack;
        using MessagePack.Formatters;

        namespace ProjectB
        {
            [GeneratedMessagePackFormatter]
            partial class MyTypeFormatter : IMessagePackFormatter<ProjectA.MyType>;

            [GeneratedMessagePackResolver]
            partial class MyResolver { }
        }
        """;

    private static MetadataReference CompileProjectA(string source, IEnumerable<MetadataReference> references)
    {
        CSharpCompilation compilation = CSharpCompilation.Create(
            "ProjectA",
            new[] { CSharpSyntaxTree.ParseText(source, new CSharpParseOptions(LanguageVersion.Latest)) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        using MemoryStream stream = new();
        var emitResult = compilation.Emit(stream);
        Assert.True(emitResult.Success, string.Join(Environment.NewLine, emitResult.Diagnostics));
        return MetadataReference.CreateFromImage(stream.ToArray());
    }

    private static async Task<string> GenerateFormatterSourceAsync(string projectASource, bool projectAReferencesMessagePack)
    {
        ImmutableArray<MetadataReference> framework = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        List<MetadataReference> messagePack = ReferencesHelper.GetReferences(ReferencesSet.MessagePack).ToList();
        List<MetadataReference> projectARefs = framework.ToList();
        if (projectAReferencesMessagePack)
        {
            projectARefs.AddRange(messagePack);
        }

        MetadataReference projectA = CompileProjectA(projectASource, projectARefs);
        List<MetadataReference> projectBRefs = framework.Concat(messagePack).ToList();
        projectBRefs.Add(projectA);

        CSharpParseOptions parseOptions = new(LanguageVersion.Latest);
        CSharpCompilation compilation = CSharpCompilation.Create(
            "ProjectB",
            new[] { CSharpSyntaxTree.ParseText(ProjectBSource, parseOptions) },
            projectBRefs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        GeneratorDriver driver = CSharpGeneratorDriver.Create(new[] { new MessagePackGenerator().AsSourceGenerator() }, parseOptions: parseOptions);
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out _, out _);
        List<string> formatterSources = driver.GetRunResult().GeneratedTrees
            .Select(t => t.GetText().ToString())
            .Where(t => t.Contains("MyTypeFormatter") && t.Contains("Serialize"))
            .ToList();
        Assert.NotEmpty(formatterSources);
        return string.Join(Environment.NewLine, formatterSources);
    }

    [Fact]
    public async Task MessagePackObjectOnReferencedType_IgnoreMemberIsHonoured()
    {
        string projectA = """
            using MessagePack;

            namespace ProjectA
            {
                [MessagePackObject]
                public class MyType
                {
                    [Key(0)]
                    public int Id { get; set; }

                    [IgnoreMember]
                    public string Secret { get; set; }
                }
            }
            """;

        string generated = await GenerateFormatterSourceAsync(projectA, projectAReferencesMessagePack: true);
        Assert.Contains("Id", generated);
        Assert.DoesNotContain("Secret", generated);
    }

    [Fact]
    public async Task DataContractOnReferencedType_NonDataMemberIsNotSerialized()
    {
        string projectA = """
            using System.Runtime.Serialization;

            namespace ProjectA
            {
                [DataContract]
                public class MyType
                {
                    [DataMember(Order = 0)]
                    public int Id { get; set; }

                    public string Secret { get; set; }
                }
            }
            """;

        string generated = await GenerateFormatterSourceAsync(projectA, projectAReferencesMessagePack: false);
        Assert.Contains("Id", generated);
        Assert.DoesNotContain("Secret", generated);
    }
}
